/**
 * Base UI adapter. The page list, titles, sections and order come from the nav
 * config: `docs/src/app/sitemap/index.ts` names the four section pages, and each
 * section page's autogenerated list gives its entries (`[Contents]`). The release
 * notes are not in that list, but the live Releases page links each one, so they
 * come from `llms/llms.txt` (the site's own index) with their order from the
 * release timeline in `llms/llms-full.txt`. Demos inline their variant source,
 * API tables come from each folder's `types.md`, and InstallationBlock and
 * ReleaseTimeline (source outside the clone) render from the package prop and
 * the site's own llms-full.txt. Pages outside the nav and the llms list are
 * reported, not written.
 */

import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs'
import { basename, dirname, extname, isAbsolute, join, relative, resolve } from 'node:path'
import { stringList } from '../lib/mdx.mjs'
import { VENDOR } from '../lib/paths.mjs'

const SOURCE = 'base-ui'
const SITE = 'https://base-ui.com'
const DOCS = 'docs/src/app/(docs)'
const SITEMAP = 'docs/src/app/sitemap/index.ts'
const BLOG = 'docs/src/app/(website)/blog/posts'
const LLMS = 'llms/llms.txt'
const LLMS_FULL = 'llms/llms-full.txt'

const TYPE_BY_SECTION = { handbook: 'guide', components: 'component', utils: 'api-reference' }
const TYPE_BY_OVERVIEW = { 'quick-start': 'install', accessibility: 'concept', releases: 'changelog', community: 'other', about: 'concept' }
const INSTALL = [['pnpm', 'pnpm add'], ['npm', 'npm i'], ['yarn', 'yarn add'], ['bun', 'bun add']]
const VARIANT_LABEL = { Tailwind: 'Tailwind', CssModules: 'CSS Modules' }
const VARIANT_ORDER = ['Tailwind', 'CssModules']

const FENCE = /^\s*(`{3,}|~{3,})/
const HEADING = /^(#{1,6})\s+(.+?)\s*$/
const ENTRY = /^- (.+?) - \(.*?\[Contents\]\(\.\/([^/)]+)\/page\.mdx\)\)/
const NAMED_IMPORT = /import\s*\{([^}]*)\}\s*from\s*['"](\.[^'"]+)['"]/g
const CSS_IMPORT = /import\s+\w+\s+from\s+['"](\.[^'"]+\.css)['"]/g
const TAG_NAME = /<((?:Demo|Types)[A-Za-z0-9]*(?:\.[A-Za-z0-9]+)?)(?=[\s/>])/g

const texts = new Map()

/** A file's text, read once per run. */
function readText(file) {
  if (!texts.has(file)) texts.set(file, readFileSync(file, 'utf8'))
  return texts.get(file)
}

function isFile(file) {
  return existsSync(file) && statSync(file).isFile()
}

function isDir(dir) {
  return existsSync(dir) && statSync(dir).isDirectory()
}

/** The first existing file among `names` in `dir`, or null. */
function firstFile(dir, names) {
  return names.map(name => join(dir, name)).find(isFile) ?? null
}

/** A file's text when it lies inside `root`, else null. */
function insideRead(root, file) {
  const rel = relative(root, file)
  if (!rel || rel.startsWith('..') || isAbsolute(rel) || !isFile(file)) return null
  return readText(file)
}

function walk(dir, out = []) {
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) walk(full, out)
    else out.push(full)
  }
  return out
}

/** Comma- or newline-separated items of a list expression, trimmed, empties dropped. */
function listItems(text) {
  return text.split(',').map(item => item.trim()).filter(Boolean)
}

function trimBlank(lines) {
  let start = 0
  let end = lines.length
  while (start < end && lines[start].trim() === '') start++
  while (end > start && lines[end - 1].trim() === '') end--
  return lines.slice(start, end)
}

/** Applies `fn` to each run of prose lines; fenced code passes through unchanged. */
function mapOutsideFences(text, fn) {
  const out = []
  let run = []
  let fence = null
  const flush = () => {
    if (run.length) out.push(fn(run.join('\n')))
    run = []
  }
  for (const line of text.split('\n')) {
    const open = line.match(FENCE)
    if (fence) {
      out.push(line)
      if (open && open[1][0] === fence[0] && open[1].length >= fence.length && line.trim() === open[1]) fence = null
    } else if (open) {
      flush()
      out.push(line)
      fence = open[1]
    } else {
      run.push(line)
    }
  }
  flush()
  return out.join('\n')
}

/** Applies `fn` to the text between backtick code spans, never inside them. */
function mapProse(segment, fn) {
  let out = ''
  let last = 0
  for (const m of segment.matchAll(/(`+)[\s\S]*?\1/g)) {
    out += fn(segment.slice(last, m.index)) + m[0]
    last = m.index + m[0].length
  }
  return out + fn(segment.slice(last))
}

/**
 * The MDX body with markup the converter cannot read normalized away: comment
 * link refs dropped, multi-line imports joined onto one line, the preload
 * `<link>` (no text) dropped, inline `<kbd>` as code, and trailing `<br />` dropped.
 */
function prepareText(raw) {
  return mapOutsideFences(raw.replace(/\r\n?/g, '\n'), run => {
    const joined = run
      .replace(/^\[\/\/\]: #.*\n?/gm, '')
      .replace(/^import\s*\{([^}]*)\}\s*from\s*(['"][^'"\n]+['"]);?/gm, (_, names, path) => {
        return `import { ${listItems(names).join(', ')} } from ${path};`
      })
      .replace(/^<link\b[\s\S]*?\/>[ \t]*\n?/gm, '')
    return mapProse(joined, part => part.replace(/<kbd>([^<]*)<\/kbd>/g, '`$1`').replace(/<br\s*\/?>[ \t]*$/gm, ''))
  })
}

/** The page's H1 (the first non-empty line), or the nav title when it has none. */
function titleOf(raw, fallback) {
  const first = raw.split('\n').find(line => line.trim() !== '') ?? ''
  const h1 = first.match(/^#\s+(.+?)\s*$/)
  return h1 ? h1[1] : fallback
}

/** The page's description: the `content` of its `<Meta name="description">`. */
function metaDescription(raw) {
  const meta = raw.match(/<Meta\b([\s\S]*?)\/>/)
  if (!meta) return ''
  const name = meta[1].match(/\bname="([^"]*)"/)
  const content = meta[1].match(/\bcontent="([^"]*)"/)
  return name?.[1] === 'description' && content ? content[1].trim() : ''
}

/** The nav's sections in order, each with the folder under react/ its section page lives in. */
function navSections(root) {
  const sitemap = readText(join(root, SITEMAP))
  const folders = new Map(
    [...sitemap.matchAll(/import\s+(\w+)\s+from\s+['"]\.\.\/\(docs\)\/react\/([^/]+)\/page\.mdx['"]/g)].map(m => [m[1], m[2]])
  )
  const call = sitemap.match(/createSitemap\(import\.meta\.url,\s*\{([^}]*)\}/)
  if (!call) throw new Error(`${SITEMAP}: no createSitemap call found`)
  return listItems(call[1]).map(key => {
    if (!folders.has(key)) throw new Error(`${SITEMAP}: sitemap key ${key} has no react/<section>/page.mdx import`)
    return { key, folder: folders.get(key) }
  })
}

/** A section page's autogenerated entries in listed order: the title and the `[Contents]` slug. */
function navEntries(sectionFile) {
  return readText(sectionFile)
    .split('\n')
    .flatMap(line => {
      const m = line.match(ENTRY)
      return m ? [{ title: m[1].trim(), slug: m[2] }] : []
    })
}

/** Slugs under react/ that llms.txt lists, such as `react/components/accordion`. */
function llmsSlugs(root) {
  return [...readText(join(root, LLMS)).matchAll(/\]\(https:\/\/base-ui\.com\/(react\/[^)\s]+?)\.md\)/g)].map(m => m[1])
}

/** The release timeline in llms-full.txt, newest first: version, latest flag, body lines. */
function timeline(root) {
  const lines = readText(join(root, LLMS_FULL)).split('\n')
  const start = lines.indexOf('#### Timeline')
  if (start === -1) return []
  const out = []
  for (let i = start + 1; i < lines.length && !/^#{1,4} /.test(lines[i]); i++) {
    const head = lines[i].match(/^##### \[(v[^\]]+)\]\(#[^)]*\)( \(Latest\))?\s*$/)
    if (head) out.push({ version: head[1], latest: Boolean(head[2]), body: [] })
    else if (out.length) out.at(-1).body.push(lines[i])
  }
  return out.map(entry => ({ ...entry, body: trimBlank(entry.body) }))
}

/** A release version as its page folder: `v1.9.0` is `v1-9-0`. */
const slugOf = version => version.replace(/\./g, '-')

/**
 * The release notes the Releases page links, newest first. llms.txt and the
 * timeline must agree; a difference stops the run rather than dropping a page.
 */
function releaseVersions(root) {
  const linked = new Set(
    llmsSlugs(root)
      .filter(slug => slug.startsWith('react/overview/releases/'))
      .map(slug => slug.slice('react/overview/releases/'.length))
  )
  const versions = timeline(root).map(entry => entry.version)
  const slugs = versions.map(slugOf)
  const diff = [...slugs.filter(slug => !linked.has(slug)), ...[...linked].filter(slug => !slugs.includes(slug))]
  if (diff.length) throw new Error(`release notes: llms.txt and the timeline disagree on ${diff.join(', ')}`)
  for (const slug of slugs) {
    if (!isFile(join(root, DOCS, 'react/overview/releases', slug, 'page.mdx'))) {
      throw new Error(`release ${slug} is in llms.txt but has no page.mdx`)
    }
  }
  return versions
}

const typeOf = (folder, slug) => {
  if (folder === 'overview') return TYPE_BY_OVERVIEW[slug] ?? 'other'
  return TYPE_BY_SECTION[folder] ?? 'other'
}

/** One live page: its MDX, title and description from the source, and the nav-given fields. */
function pageOf(root, { folder, path, fallback, section, type }) {
  const file = join(root, DOCS, 'react', folder, path, 'page.mdx')
  if (!isFile(file)) throw new Error(`nav entry react/${folder}/${path} has no page.mdx`)
  const raw = readText(file)
  return {
    slug: `react/${folder}/${path}`,
    title: titleOf(raw, fallback),
    description: metaDescription(raw),
    url: `${SITE}/react/${folder}/${path}`,
    section,
    type,
    path: `vendor/docs/${SOURCE}/${DOCS}/react/${folder}/${path}/page.mdx`,
    file,
    format: 'mdx',
    text: prepareText(raw),
  }
}

/** Live pages the nav and llms.txt do not cover, with the reason, for the report. */
function notWritten(root, written) {
  const lines = []
  const docsRoot = join(root, DOCS)
  for (const file of walk(docsRoot).filter(f => basename(f) === 'page.mdx')) {
    const slug = relative(docsRoot, dirname(file))
    if (written.has(slug)) continue
    const sectionIndex = /^react(\/[^/]+)?$/.test(slug)
    const reason = sectionIndex
      ? 'section index: autogenerated contents page, marked noindex and private; not in the nav or llms.txt'
      : slug.startsWith('react/')
        ? 'not in the nav or llms.txt'
        : 'docs app page outside react/: not in the nav or llms.txt, and no docs page links it'
    lines.push(`${slug} (${reason})`)
  }
  for (const dir of readdirSync(join(root, BLOG)).sort()) {
    if (isFile(join(root, BLOG, dir, 'post.mdx'))) {
      lines.push(`blog/${dir} (blog post: the docs nav does not link /blog; only the site home does)`)
    }
  }
  return lines
}

// ---- Hooks ----------------------------------------------------------------

const INSTALL_HOOK = props => {
  const pkg = typeof props.package === 'string' ? props.package : ''
  if (!pkg) return null
  return INSTALL.map(([manager, verb]) => `**${manager}**\n\n\`\`\`bash\n${verb} ${pkg}\n\`\`\``).join('\n\n')
}

/** The release timeline from llms-full.txt, with each version linked to its own page. */
function releaseTimelineMarkdown(ctx) {
  const entries = timeline(ctx.root)
  if (!entries.length) return null
  const lines = []
  for (const entry of entries) {
    const link = `[${entry.version}](${SITE}/react/overview/releases/${slugOf(entry.version)})`
    lines.push(`**${link}**${entry.latest ? ' (Latest)' : ''}`, '', ...entry.body, '')
  }
  return lines.join('\n').trim()
}

function codeBlock(lang, title, body) {
  const text = body.replace(/\n+$/, '')
  const mark = text.includes('```') ? '~~~~' : '```'
  return [`${mark}${lang} title="${title}"`, ...text.split('\n'), mark]
}

/** The import path the page gives for `name`, when it imports it by name. */
function importPath(pageText, name) {
  for (const m of pageText.matchAll(NAMED_IMPORT)) {
    if (listItems(m[1]).includes(name)) return m[2]
  }
  return null
}

/** The variant keys of `createDemo*(import.meta.url, { ... })`, Tailwind first as the site shows them. */
function variantKeys(indexText) {
  const m = indexText.match(/createDemo\w*\(\s*import\.meta\.url\s*,\s*\{([^}]*)\}/)
  if (!m) return []
  const rank = key => {
    const i = VARIANT_ORDER.indexOf(key)
    return i === -1 ? VARIANT_ORDER.length : i
  }
  return listItems(m[1]).sort((a, b) => rank(a) - rank(b))
}

function variantFolder(dir, indexText, key) {
  const m = indexText.match(new RegExp(`import\\s+${key}\\s+from\\s+['"](\\.[^'"]+)['"]`))
  return m ? resolve(dir, m[1]) : null
}

/** A demo's source: each variant's entry file, then the CSS that file imports. */
function demoMarkdown(name, ctx) {
  const rel = importPath(readText(ctx.file), name)
  if (!rel) return null
  const dir = resolve(dirname(ctx.file), rel)
  if (!isDir(dir)) return null
  const indexFile = firstFile(dir, ['index.ts', 'index.tsx'])
  const indexText = indexFile ? readText(indexFile) : ''
  const keys = variantKeys(indexText)
  const variants = keys.length
    ? keys.map(key => ({ key, folder: variantFolder(dir, indexText, key) }))
    : [{ key: '', folder: dir }]
  const out = []
  for (const { key, folder } of variants) {
    const entry = folder && firstFile(folder, ['index.tsx', 'index.ts', 'index.jsx', 'index.js'])
    if (!entry) continue
    const source = readText(entry)
    if (key) out.push(`**${VARIANT_LABEL[key] ?? key}**`, '')
    out.push(...codeBlock(extname(entry).slice(1), basename(entry), source), '')
    for (const m of source.matchAll(CSS_IMPORT)) {
      const css = insideRead(ctx.root, resolve(folder, m[1]))
      if (css !== null) out.push(...codeBlock('css', basename(m[1]), css), '')
    }
  }
  return out.length ? out.join('\n').trim() : null
}

/** A types.md file's H3 blocks, grouped by their H2: `api` (API Reference) and `additional`. */
function parseTypes(text) {
  const doc = { api: [], additional: [] }
  let h2 = ''
  let block = null
  let fence = null
  for (const line of text.split('\n')) {
    const open = line.match(FENCE)
    if (fence) {
      if (block) block.body.push(line)
      if (open && open[1][0] === fence[0] && open[1].length >= fence.length && line.trim() === open[1]) fence = null
      continue
    }
    if (open) {
      fence = open[1]
      if (block) block.body.push(line)
      continue
    }
    const h = line.match(HEADING)
    if (h && h[1].length === 2) {
      h2 = h[2]
      block = null
    } else if (h && h[1].length === 3) {
      block = { title: h[2], body: [] }
      if (h2 === 'API Reference') doc.api.push(block)
      else if (h2 === 'Additional Types') doc.additional.push(block)
    } else if (h && h[1].length === 1) {
      block = null
    } else if (block) {
      block.body.push(line)
    }
  }
  for (const b of [...doc.api, ...doc.additional]) b.body = trimBlank(b.body)
  return doc
}

/** A part's H3 block and its `Part.*` blocks that follow it (Root, Root.Props, Root.State). */
function partGroup(blocks, part) {
  const key = part.toLowerCase()
  const head = blocks.findIndex(block => block.title.toLowerCase() === key)
  if (head === -1) return []
  const group = [blocks[head]]
  for (const block of blocks.slice(head + 1)) {
    if (!block.title.toLowerCase().startsWith(`${key}.`)) break
    group.push(block)
  }
  return group
}

/** The heading the marker sits under on the page: its level and text (H1 when none). */
function nearestHeading(file, name) {
  const lines = readText(file).split('\n')
  const marker = new RegExp(`<${name.replace(/\./g, '\\.')}(?![\\w.])`)
  const at = lines.findIndex(line => marker.test(line))
  let found = { level: 1, text: '' }
  let fence = null
  for (const line of lines.slice(0, at === -1 ? lines.length : at)) {
    const open = line.match(FENCE)
    if (fence) {
      if (open && open[1][0] === fence[0] && open[1].length >= fence.length && line.trim() === open[1]) fence = null
      continue
    }
    if (open) {
      fence = open[1]
      continue
    }
    const h = line.match(HEADING)
    if (h) found = { level: h[1].length, text: h[2] }
  }
  return found
}

/**
 * An API table from the folder's types.md. The page already has the heading the
 * marker sits under, so that block's own heading is dropped and its parts sit one
 * level below it. `TypesX.Part` and `TypesX` take the Part block; `...Additional...`
 * takes the Additional Types blocks, filtered by `showAdditionalTypes` when given.
 */
function typesMarkdown(name, props, ctx) {
  const typesFile = join(dirname(ctx.file), 'types.md')
  if (!isFile(typesFile)) return null
  const doc = parseTypes(readText(typesFile))
  const near = nearestHeading(ctx.file, name)
  const level = Math.min(6, near.level + 1)
  let group
  if (name.includes('Additional')) {
    const only = stringList(props.showAdditionalTypes).map(s => s.toLowerCase())
    group = doc.additional.filter(block => !only.length || only.includes(block.title.toLowerCase()))
  } else {
    group = partGroup(doc.api, name.includes('.') ? name.slice(name.indexOf('.') + 1) : name.replace(/^Types/, ''))
  }
  if (!group.length) return null
  const lines = []
  group.forEach((block, i) => {
    const duplicate = i === 0 && block.title.toLowerCase() === near.text.toLowerCase()
    if (!duplicate) lines.push(`${'#'.repeat(level)} ${block.title}`, '')
    lines.push(...block.body, '')
  })
  return lines.join('\n').replace(/&#xA;/g, ' ').replace(/\n{3,}/g, '\n\n').trim()
}

/** Every Demo* and Types* tag the page sources use, so each gets a hook. */
function tagNames(reactDir) {
  const names = new Set()
  if (!isDir(reactDir)) return names
  for (const file of walk(reactDir).filter(f => basename(f) === 'page.mdx')) {
    for (const m of readText(file).matchAll(TAG_NAME)) names.add(m[1])
  }
  return names
}

const REACT_DIR = join(VENDOR, SOURCE, DOCS, 'react')

/** Fixed site components, then one hook per Demo* or Types* tag. */
function buildComponents() {
  const table = {
    Subtitle: (props, children) => children,
    Meta: () => '',
    InstallationBlock: props => INSTALL_HOOK(props),
    ReleaseTimeline: (props, children, ctx) => releaseTimelineMarkdown(ctx),
  }
  for (const name of tagNames(REACT_DIR)) {
    table[name] = name.startsWith('Demo')
      ? (props, children, ctx) => demoMarkdown(name, ctx)
      : (props, children, ctx) => typesMarkdown(name, props, ctx)
  }
  return table
}

export default {
  source: SOURCE,

  async collect({ vendorDir, entry }) {
    const root = join(vendorDir, SOURCE)
    const report = []
    const pages = []
    const navTitles = new Map()
    const sections = navSections(root)
    const versions = releaseVersions(root)

    for (const section of sections) {
      const sectionLabel = `React / ${section.key}`
      const listing = join(root, DOCS, 'react', section.folder, 'page.mdx')
      for (const item of navEntries(listing)) {
        const page = pageOf(root, {
          folder: section.folder,
          path: item.slug,
          fallback: item.title,
          section: sectionLabel,
          type: typeOf(section.folder, item.slug),
        })
        navTitles.set(page.slug, item.title)
        pages.push(page)
        if (section.folder === 'overview' && item.slug === 'releases') {
          for (const version of versions) {
            const child = pageOf(root, {
              folder: 'overview',
              path: `releases/${slugOf(version)}`,
              fallback: version,
              section: `${sectionLabel} / Releases`,
              type: 'changelog',
            })
            navTitles.set(child.slug, version)
            pages.push(child)
          }
        }
      }
    }

    const written = new Set(pages.map(page => page.slug))
    const llms = llmsSlugs(root)
    const missing = llms.filter(slug => !written.has(slug))
    const extra = [...written].filter(slug => !llms.includes(slug))
    if (missing.length || extra.length) {
      throw new Error(`llms.txt cross-check: missing ${missing.join(', ') || 'none'}; extra ${extra.join(', ') || 'none'}`)
    }
    const retitled = pages.filter(page => navTitles.get(page.slug) !== page.title).map(page => `${navTitles.get(page.slug)} -> ${page.title}`)
    const releaseCount = versions.length

    report.push(
      `nav: ${pages.length - releaseCount} pages from ${sections.length} section listings; ${releaseCount} release notes linked from the Releases page`
    )
    report.push(`llms.txt: ${llms.length} entries; in output ${written.size}; missing ${missing.length}; extra ${extra.length}`)
    report.push(`nav title vs page H1 differences: ${retitled.length}${retitled.length ? ` (${retitled.join(' | ')})` : ''}`)
    const excluded = notWritten(root, written)
    report.push(`not written (${excluded.length}): ${excluded.join(' | ')}`)

    return { root, siteUrl: SITE, pages, report }
  },
}

export const components = buildComponents()
